Q: iText 7 copyPagesTo throws UnsupportedOperationException for a link annotation with an invalid GoTo destination A: <pre><code>// Source - https://stackoverflow.com/q/11415665
// Posted by owsata, modified by community. See post 'Timeline' for change history
// Retrieved 2026-07-22, License - CC BY-SA 4.0

&lt;!doctype&gt;
&lt;html&gt;
&lt;head&gt;
   &lt;title&gt;jsPDF&lt;/title&gt;
   &lt;script type=&quot;text/javascript&quot; src=&quot;../libs/base64.js&quot;&gt;&lt;/script&gt;
   &lt;script type=&quot;text/javascript&quot; src=&quot;../libs/sprintf.js&quot;&gt;&lt;/script&gt;
   &lt;script type=&quot;text/javascript&quot; src=&quot;../jspdf.js&quot;&gt;&lt;/script&gt;

       &lt;script type=&quot;text/javascript&quot;&gt;

        function demo1() {
            jsPDF.init();
            jsPDF.addPage();
            jsPDF.text(20, 20, 'Hello world!');
            jsPDF.text(20, 30, 'This is client-side Javascript, pumping out a PDF.');

            // Making Data URI
            var out = jsPDF.output();
            var url = 'data:application/pdf;base64,' + Base64.encode(out);

            document.location.href = url;
         }
    &lt;/script&gt;
&lt;/head&gt;
&lt;body&gt;

&lt;a href=&quot;javascript:demo1()&quot;&gt;Run Code&lt;/a&gt;

&lt;/body&gt;
&lt;/html&gt;
</code></pre>
